(* KEEP="TRUE" *) reg sr_cpu_selected, sr_restore_low, sr_restore_high;
(* KEEP="TRUE" *) wire [8:0] sr_cpu_data;
wire [8:0] sr_late_data;
wire sr_write_low, sr_write_high, sr_write_hold;
always @* begin
 sr_cpu_selected = 1'b0;
 case(insn_state)
  STATE_STORE: case(op)
   I_OP, I_RT: case(op_dst)
    4'b0111: sr_cpu_selected = 1'b1;
   endcase
   I_LD: case(ld_dst)
    4'b0111: sr_cpu_selected = 1'b1;
   endcase
  endcase
 endcase
end
always @* begin
 sr_restore_low = 1'b0;
 sr_restore_high = 1'b0;
 if(ss_wr) begin
  if(ss_wa >= 8'h34 && ss_wa <= 8'h53) begin
  end else case(ss_wa)
   8'h0c: sr_restore_low = 1'b1;
   8'h0d: sr_restore_high = 1'b1;
  endcase
 end
end
assign sr_cpu_data = (op == I_LD) ? {ld_id[14], ld_id[13], ld_id[11], ld_id[10], ld_id[9], ld_id[8], ld_id[7], ld_id[1], ld_id[0]} : {idb[14], idb[13], idb[11], idb[10], idb[9], idb[8], idb[7], idb[1], idb[0]};
