 input reset_n, frozen, cpu_selected, restore_selected, output reg write
);
always @* begin
 write = RESET_WRITE;
 if (reset_n & ~frozen) write = cpu_selected;
 else if (reset_n & frozen) write = restore_selected;
end
endmodule
(* LUT_MAP="yes" *)
module dsp_status_late_data(
 input reset_n, frozen, cpu_data, restore_data, output reg value
);
always @* begin
 value = 1'b0;
 if (reset_n & ~frozen) value = cpu_data;
 else if (reset_n & frozen) value = restore_data;
end
endmodule

